-- 02_topics_repurpose.sql — UPDATE topics 1-5 (title/context/sources only)
UPDATE public.topics SET proposition='Should influencers be legally required to disclose filters and retouching?', category='Entertainment', context='France passed a 2023 law requiring influencers to disclose retouched or filtered images in paid posts. The UK, US states, and the platforms themselves have debated similar rules amid concerns about body image and deceptive advertising.', sources='[{"title": "France: influencer law guidance", "url": "https://www.economie.gouv.fr/particuliers/influenceurs"}, {"title": "Dove Self-Esteem Project", "url": "https://www.dove.com/us/en/dove-self-esteem-project.html"}, {"title": "UK Advertising Standards Authority", "url": "https://www.asa.org.uk"}]'::jsonb, is_featured=false WHERE id=1;
UPDATE public.topics SET proposition='Should factory farming be phased out within ten years?', category='Lifestyle', context='Industrial livestock production faces scrutiny over emissions, animal welfare, and antibiotic resistance. California''s Proposition 12 and EU debates over caged farming have tested how far regulation can go.', sources='[{"title": "FAO: livestock emissions (GLEAM)", "url": "https://www.fao.org/gleam"}, {"title": "CDC: antimicrobial resistance", "url": "https://www.cdc.gov/antimicrobial-resistance/"}, {"title": "California Dept. of Food and Agriculture: Animal Care Program", "url": "https://www.cdfa.ca.gov/ahfss/AnimalCare/"}]'::jsonb, is_featured=false WHERE id=2;
UPDATE public.topics SET proposition='Should people with felony convictions automatically regain voting rights after serving their sentences?', category='Politics', context='In 2018, Florida voters approved Amendment 4, restoring voting rights to most people with felony convictions after they complete their sentences. An estimated 4.4 million Americans remain disenfranchised under state laws, while Maine and Vermont allow voting even from prison.', sources='[{"title": "Sentencing Project: Locked Out 2022", "url": "https://www.sentencingproject.org/publications/locked-out-2022-estimates-of-people-denied-voting-rights/"}, {"title": "Brennan Center: Voting Rights Restoration", "url": "https://www.brennancenter.org/issues/ensure-every-american-can-vote/voting-rights-restoration"}, {"title": "AP: Voting Rights", "url": "https://apnews.com/hub/voting-rights"}]'::jsonb, is_featured=false WHERE id=3;
UPDATE public.topics SET proposition='Should unrealized capital gains be taxed?', category='Business', context='The White House has proposed a 25% minimum tax on households worth more than $100 million, applied to income including unrealized capital gains. Supporters say the wealthy borrow against stock to avoid taxes; critics call the idea unconstitutional and unworkable.', sources='[{"title": "White House: Billionaire Minimum Income Tax", "url": "https://www.whitehouse.gov/briefing-room/statements-releases/"}, {"title": "Tax Policy Center", "url": "https://www.taxpolicycenter.org/"}, {"title": "Reuters: Business News", "url": "https://www.reuters.com/business/"}]'::jsonb, is_featured=false WHERE id=4;
UPDATE public.topics SET proposition='Should movie theaters make phone-free screenings the default?', category='Entertainment', context='Alamo Drafthouse built its brand on a strict no-talking, no-texting policy, while concerts and comedy tours increasingly seal phones in locking pouches. With glowing screens ranking among moviegoers'' top theater complaints, some argue phone-free should be the default and phone-friendly screenings the exception.', sources='[{"title": "Alamo Drafthouse: No Talking, No Texting Policy", "url": "https://drafthouse.com/"}, {"title": "Yondr: Phone-Free Spaces for Concerts and Shows", "url": "https://www.overyondr.com/"}, {"title": "AP News: Movie Box Office Reporting", "url": "https://apnews.com/hub/movies"}]'::jsonb, is_featured=false WHERE id=5;
SELECT id, proposition, category FROM public.topics WHERE id BETWEEN 1 AND 5 ORDER BY id;
